import { z } from 'zod';
/**
 * Builds a Zod schema that can validate and parse arbitrary objects into a BlockConfiguration.
 * This schema uses a discriminated union based on the 'type' field to determine which block schema to apply.
 *
 * @param blocks A dictionary of document blocks, each with a schema and a React component.
 * @returns A Zod schema that can validate and parse objects into a BlockConfiguration<T>.
 */
export function buildBlockConfigurationSchema(blocks) {
    const blockObjects = Object.keys(blocks).map((type) => z.object({
        type: z.literal(type),
        data: blocks[type].schema,
    }));
    return z.discriminatedUnion('type', blockObjects).transform((v) => v);
}
