            const sourceContainerId = get().getItemParentColumnsContainerBlockId(sourceId);
            if (!sourceContainerId)
                throw new Error('Source container not found');
            const sourceContainer = document[sourceContainerId];
            // Remove the sourceId from its current column
            sourceContainer.data.childrenIds = sourceContainer.data.childrenIds.map((column) => column.filter((id) => id !== sourceId));
            document[sourceContainerId] = sourceContainer;
