            const fetchPromises = Object.entries(postTypeMap).map(async ([postType, ids]) => {
                const posts = await wordpressApi.fetchAllPosts(ids, postType);
                return { postType, posts };
            });
            const fetchedResults = await Promise.all(fetchPromises);
