import { TEXT_SIZE_VALUES } from './typography';
import { FONT_FAMILIES } from './constants/fontFamily';
export function getPadding(padding) {
    if (!padding)
        return '0';
    const { top = 0, right = 0, bottom = 0, left = 0 } = padding;
    return `${top}px ${right}px ${bottom}px ${left}px`;
}
export function getFontFamily(fontFamily) {
    const family = FONT_FAMILIES.find(f => f.key === fontFamily);
    return family?.value ?? FONT_FAMILIES[0].value;
}
export function getFontSize(size) {
    if (typeof size === 'number')
        return size;
    if (!size)
        return TEXT_SIZE_VALUES.m;
    return TEXT_SIZE_VALUES[size];
}
// utils.ts
export function getBorderRadius(type, value) {
    if (typeof value === 'number')
        return value;
    if (type === 'image') {
        switch (value) {
            case 'none':
                return 0;
            case 'small':
                return 4;
            case 'medium':
                return 8;
            case 'large':
                return 16;
            case 'full':
                return '50%'; // Changed from 'circle' to 'full'
            default:
                return 0;
        }
    }
    // For buttons
    switch (value) {
        case 'rectangle':
            return 0;
        case 'pill':
            return 9999;
        case 'rounded':
            return 4;
        default:
            return 4;
    }
}
