/**
 * Creates the UI slice for the Zustand store.
 */
export const createUISlice = (set, get) => ({
    selectedBlockId: 'root',
    selectedSidebarTab: 'styles',
    selectedScreenSize: 'desktop',
    isInspectorDrawerOpen: true,
    isBlockBeingDragged: false,
    /**
     * Sets the selected block ID and updates related UI states.
     * @param selectedBlockId - The ID of the selected block.
     */
    setSelectedBlockId: (selectedBlockId) => {
        set({
            selectedBlockId,
            selectedSidebarTab: selectedBlockId ? 'block-configuration' : 'styles',
            isInspectorDrawerOpen: selectedBlockId ? true : get().isInspectorDrawerOpen,
        });
    },
    /**
     * Sets the current sidebar tab.
     * @param selectedSidebarTab - The sidebar tab to select.
     */
    setSidebarTab: (selectedSidebarTab) => set({ selectedSidebarTab }),
    /**
     * Sets the current screen size.
     * @param selectedScreenSize - The screen size to set.
     */
    setSelectedScreenSize: (selectedScreenSize) => set({ selectedScreenSize }),
    /**
     * Toggles the state of the inspector drawer.
     */
    toggleInspectorDrawer: () => set((state) => ({ isInspectorDrawerOpen: !state.isInspectorDrawerOpen })),
    /**
     * Sets the dragging state of a block.
     * @param isDragging - Whether a block is being dragged.
     */
    setBlockDraggingState: (isDragging) => set({ isBlockBeingDragged: isDragging }),
});
